class Employee:
    def __init__(self, name, salary):
        self.name = name
        self.salary = salary

    def pay(self):
        return self.salary

    @classmethod
    def from_string(cls, text):
        name, salary = text.split(':')
        return cls(name, int(salary))


class Manager(Employee):
    def __init__(self, name, salary, bonus=0):
        super().__init__(name, salary)
        self.bonus = bonus
        self.reports = []

    def pay(self):
        return super().pay() + self.bonus

    def add_report(self, employee):
        self.reports.append(employee)

    def team_cost(self):
        return sum(r.pay() for r in self.reports)

